using System;using System.Linq;using System.Reflection;using NUnit.Framework;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;
namespace LWS.TruckSubmarine.Tests {
 public sealed class SubmarineFogAndViewportTests {
  const BindingFlags Any=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;static Type Sports(string n)=>Type.GetType("LWS.TruckSports."+n+", Assembly-CSharp",true);static object Get(object x,string n)=>x.GetType().GetField(n,Any)is FieldInfo f?f.GetValue(x):x.GetType().GetProperty(n,Any).GetValue(x);static void Set(object x,string n,object v)=>x.GetType().GetField(n,Any).SetValue(x,v);
  [Test]public void ExistingBogKeepsDefaultDensityAndAllOldModesKeepOriginalInnerAnchors(){var root=new GameObject("Default presentation fixture only");var water=new GameObject("Actual local water reference");var old=new GameObject("Original Bog anchor fixture only");var sub=new GameObject("Submarine anchor fixture only");try{var camera=root.AddComponent<Camera>();camera.transform.position=Vector3.down*10;var effect=root.AddComponent(Type.GetType("LWS.TruckBogSnorkelling.BogCameraEffects, Assembly-CSharp",true));Assert.That((float)Get(effect,"densityScale"),Is.EqualTo(1));Set(effect,"waterSurface",water.transform);Set(effect,"waterBounds",new Bounds(Vector3.zero,Vector3.one*1000));Assert.That((bool)effect.GetType().GetMethod("Evaluate").Invoke(effect,new object[]{camera}),Is.True);Assert.That(((MaterialPropertyBlock)Get(effect,"Properties")).GetFloat("_BogDensityScale"),Is.EqualTo(1));var legacy=old.AddComponent(Type.GetType("LWS.TruckBogSnorkelling.BogMatch, Assembly-CSharp",true));var submarine=sub.AddComponent(Type.GetType("LWS.TruckSubmarine.SubmarineMatch, Assembly-CSharp",true));var method=Sports("SportsEventSession").GetMethod("ViewportCardAnchor");var inner=Sports("SportsCompactViewportHud").GetMethod("InnerAnchor");foreach(var viewport in new[]{new Rect(0,.5f,.5f,.5f),new Rect(.5f,.5f,.5f,.5f),new Rect(0,0,.5f,.5f),new Rect(.5f,0,.5f,.5f),new Rect(0,0,1,1)}){Assert.That((Vector2)method.Invoke(legacy,new object[]{0,viewport}),Is.EqualTo((Vector2)inner.Invoke(null,new object[]{viewport})));Assert.That((Vector2)method.Invoke(submarine,new object[]{0,viewport}),Is.EqualTo(new Vector2(0,1)));}var protectedNames=new[]{"LWS.TruckBaseJumping.BaseJumpMatch","LWS.TruckMattressRacing.MattressMatch","LWS.TruckHotPotato.HotPotatoMatch"};foreach(var name in protectedNames){var type=Type.GetType(name+", Assembly-CSharp",true);Assert.That(type.GetMethod("ViewportCardAnchor").DeclaringType,Is.EqualTo(Sports("SportsEventSession")),name+" retains the existing inherited layout.");}}finally{UnityEngine.Object.DestroyImmediate(root);UnityEngine.Object.DestroyImmediate(water);UnityEngine.Object.DestroyImmediate(old);UnityEngine.Object.DestroyImmediate(sub);}}
  static Color[] Render(Shader shader,MaterialPropertyBlock properties){const int size=16;var source=new Texture2D(2,2,TextureFormat.RGBAFloat,false,true);source.SetPixels(Enumerable.Repeat(new Color(.75f,.5f,.2f,1),4).ToArray());source.Apply();var depth=new Texture2D(2,2,TextureFormat.RFloat,false,true);depth.SetPixels(Enumerable.Repeat(new Color(.5f,0,0,1),4).ToArray());depth.Apply();var rt=new RenderTexture(size,size,0,RenderTextureFormat.ARGBFloat,RenderTextureReadWrite.Linear);var read=new Texture2D(size,size,TextureFormat.RGBAFloat,false,true);var material=new Material(shader);var cmd=new CommandBuffer();var prior=RenderTexture.active;var z=Shader.GetGlobalVector("_ZBufferParams");var bias=Shader.GetGlobalVector("_BlitScaleBias");var oldSource=Shader.GetGlobalTexture("_BlitTexture");var oldDepth=Shader.GetGlobalTexture("_CameraDepthTexture");try{rt.Create();cmd.SetRenderTarget(rt);cmd.SetViewport(new Rect(0,0,size,size));cmd.ClearRenderTarget(false,true,Color.magenta);cmd.SetGlobalVector("_ZBufferParams",new Vector4(0,0,0,1f/20));cmd.SetGlobalVector("_BlitScaleBias",new Vector4(1,1,0,0));cmd.SetGlobalTexture("_BlitTexture",source);cmd.SetGlobalTexture("_CameraDepthTexture",depth);cmd.DrawProcedural(Matrix4x4.identity,material,0,MeshTopology.Triangles,3,1,properties);Graphics.ExecuteCommandBuffer(cmd);RenderTexture.active=rt;read.ReadPixels(new Rect(0,0,size,size),0,0);read.Apply();return read.GetPixels();}finally{RenderTexture.active=prior;Shader.SetGlobalVector("_ZBufferParams",z);Shader.SetGlobalVector("_BlitScaleBias",bias);Shader.SetGlobalTexture("_BlitTexture",oldSource);Shader.SetGlobalTexture("_CameraDepthTexture",oldDepth);cmd.Release();rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(read);UnityEngine.Object.DestroyImmediate(material);UnityEngine.Object.DestroyImmediate(depth);UnityEngine.Object.DestroyImmediate(source);}}
  [Test]public void ActualGpuDefaultOneMatchesFrozenLegacyShaderWhileSubDensityRetainsMoreSceneContrast(){Assert.That(SystemInfo.graphicsDeviceType,Is.Not.EqualTo(GraphicsDeviceType.Null));var current=Resources.Load<Shader>("TruckBog/BogUnderwater");var reference=AssetDatabase.LoadAssetAtPath<Shader>("Assets/TruckSubmarine/Tests/EditMode/Fixtures/LegacyBogUnderwaterGpuReference.shader");Assert.That(current!=null&&reference!=null,Is.True);var props=new MaterialPropertyBlock();props.SetFloat("_BogSubmersion",10);props.SetFloat("_BogClock",0);props.SetFloat("_BogDensityScale",1);props.SetVector("_BogViewport",new Vector4(0,0,1,1));var baseline=Render(reference,props);var unchanged=Render(current,props);float maxError=0;for(int i=0;i<baseline.Length;i++)maxError=Mathf.Max(maxError,Mathf.Abs(baseline[i].r-unchanged[i].r),Mathf.Abs(baseline[i].g-unchanged[i].g),Mathf.Abs(baseline[i].b-unchanged[i].b));Assert.That(maxError,Is.LessThan(.00002f),"Original Bog default1 must match frozen previous actual shader pixels.");props.SetFloat("_BogDensityScale",.35f);var clearer=Render(current,props);var fog=new Vector3(.09f,.23f,.21f);for(int i=0;i<baseline.Length;i++){float original=Vector3.Distance(new Vector3(baseline[i].r,baseline[i].g,baseline[i].b),fog);float improved=Vector3.Distance(new Vector3(clearer[i].r,clearer[i].g,clearer[i].b),fog);Assert.That(improved,Is.GreaterThan(original*1.5f));}props.SetVector("_BogViewport",new Vector4(0,0,.5f,1));var half=Render(current,props);for(int y=0;y<16;y++)for(int x=9;x<16;x++){var c=half[y*16+x];Assert.That(c.r,Is.EqualTo(.75f).Within(.00002f));Assert.That(c.g,Is.EqualTo(.5f).Within(.00002f));Assert.That(c.b,Is.EqualTo(.2f).Within(.0001f));}TestContext.WriteLine("BOG_DEFAULT_GPU maximumLegacyError="+maxError.ToString("R")+"; reduced density affects only selected camera viewport, no Windows/human visual acceptance.");}
 }
